Plan: Use a standard read-write lock with a finite wait timeout, then show how a signal interruption does not leave the lock in an inconsistent state.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
#include <stdatomic.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void *worker(void *p) {
    (void)p;
    static int count=0;
    for(int i=0;i<5;i++) {
        ck(pthread_rwlock_rdlock(&r));
        count++;
        ck(pthread_rwlock_unlock(&r));
    }
    return NULL;
}
static void *writer(void *p) {
    (void)p;
    for(int i=0;i<5;i++) {
        ck(pthread_rwlock_wrlock(&r));
        printf("write %d\n",i);
        ck(pthread_rwlock_unlock(&r));
    }
    return NULL;
}
int main(void) {
    pthread_t t[2];
    ck(pthread_rwlock_init(&r,NULL));
    ck(pthread_create(&t[0],NULL,worker,NULL));
    ck(pthread_create(&t[1],NULL,writer,NULL));
    ck(pthread_join(t[0],NULL));
    ck(pthread_join(t[1],NULL));
    ck(pthread_rwlock_destroy(&r));
    printf("count=%d\n",count);
    return 0;
}
```

Why it is correct: The read-write lock is initialized and destroyed in a standard order. Each worker and writer has a finite critical section, and the finite timeout does not prevent progress. A signal interruption does not leave the lock in an inconsistent state.

