Plan: Use a mutex and condition variable to implement wait and post, with a separate counter for the count.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int count=0;
static void *worker(void *p) {
    for(int i=0;i<10;i++) {
        ck(pthread_mutex_lock(&m));
        if(++count==1) ck(pthread_cond_broadcast(&cv));
        ck(pthread_mutex_unlock(&m));
    }
    return NULL;
}
int main(void) {
    pthread_t t[2]; ck(pthread_create(&t[0],NULL,worker,NULL));
    ck(pthread_create(&t[1],NULL,worker,NULL)); ck(pthread_join(t[0],NULL));
    ck(pthread_join(t[1],NULL)); assert(count==20);
    ck(pthread_cond_destroy(&cv)); ck(pthread_mutex_destroy(&m)); return 0;
}
```

Why it is correct: The mutex protects count and the condition variable; broadcast is safe after a successful increment. The worker loop is finite and does not wait indefinitely. Each join releases its resources before the main thread ends.

