#include <time.h>
#include <string.h>
#include <stdbool.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void ckp(sem_t *s) { if (sem_trywait(s)==-1 && errno!=EAGAIN) { fprintf(stderr,"sem error\n"); exit(1); } }
static void ckv(sem_t *s) { if (sem_post(s)==-1) { fprintf(stderr,"sem error\n"); exit(1); } }
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static int gen=0, h=0, o=0;
static void *h2o(void *p) {
    (void)p; int *id=*(int **)p;
    for(int i=0;i<10;i++) {
        ckp(&m); gen++; ckv(&m);
        ckp(&m); h++; ckv(&m);
        ckp(&m); o++; ckv(&m);
        ckp(&m); gen++; ckv(&m);
        ckp(&m); h++; ckv(&m);
        ckp(&m); o++; ckv(&m);
        ckp(&m); gen++; ckv(&m);
        ckp(&m); h++; ckv(&m);
        ckp(&m); o++; ckm(&m);
    }
    return NULL;
}
static void *h(void *p) {
    (void)p; for(int i=0;i<10;i++) {
        ckp(&m); gen++; ckv(&m);
        ckp(&m); h++; ckv(&m);
        ckp(&m); o++; ckv(&m);
        ckp(&m); gen++; ckv(&m);
        ckp(&m); h++; ckv(&m);
        ckp(&m); o++; ckv(&m);
        ckp(&m); gen++; ckv(&m);
        ckp(&m); h++; ckv(&m);
        ckp(&m); o++; ckv(&m);
    } return NULL;
}
static void *o(void *p) {
    (void)p; for(int i=0;i<10;i++) {
        ckp(&m); gen++; ckv(&m);
        ckp(&m); h++; ckv(&m);
        ckp(&m); o++; ckv(&m);
        ckp(&m); gen++; ckv(&m);
        ckp(&m); h++; ckv(&m);
        ckp(&m); o++; ckv(&m);
        ckp(&m); gen++; ckv(&m);
        ckp(&m); h++; ckv(&m);
        ckp(&m); o++; ckv(&m);
    } return NULL;
}
int main(void) {
    pthread_t th[3]; int id[3]={1,2,3};
    for(int i=0;i<3;i++) ck(pthread_create(&th[i],NULL,h2o,&id[i]));
    for(int i=0;i<3;i++) ck(pthread_join(th[i],NULL));
    assert(h==30 && o==30);
    printf("h=%d o=%d\n",h,o);
    return 0;
}
