Plan: Use one mutex and one condition variable to protect the shared state and operations.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <limits.h>
#include <sched.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
#define CK(e) do { int _e=e; ck(_e); } while (0)
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int head,tail,n;
static void *enqueue(void *p) {
    (void)p; for (int i=0;i<10;i++) {
        CK(pthread_mutex_lock(&m));
        while ((tail+1)%10==head) { ck(pthread_cond_wait(&cv,&m)); }
        head=(head+1)%10; n++;
        CK(pthread_mutex_unlock(&m));
    } return NULL;
}
static void *dequeue(void *p) {
    (void)p; for (int i=0;i<10;i++) {
        CK(pthread_mutex_lock(&m));
        while (head==tail && n==0) { ck(pthread_cond_wait(&cv,&m)); }
        assert(n>0); int x=(tail+1)%10; tail=x; n--;
        CK(pthread_mutex_unlock(&m));
    } return NULL;
}
static void *report(void *p) {
    (void)p; for (int i=0;i<10;i++) {
        CK(pthread_mutex_lock(&m)); assert(n>0); assert(head!=tail); CK(pthread_mutex_unlock(&m));
    } return NULL;
}
int main(void) {
    pthread_t t[3]; CK(pthread_create(&t[0],NULL,enqueue,NULL));
    CK(pthread_create(&t[1],NULL,dequeue,NULL));
    CK(pthread_create(&t[2],NULL,report,NULL));
    for (int i=0;i<3;i++) CK(pthread_join(t[i],NULL));
    assert(head!=tail); assert(n==0); printf("queue test passed\n");
    pthread_cond_destroy(&cv); pthread_mutex_destroy(&m); return 0;
}
```

Why it is correct: The single mutex protects head, tail, and n. The condition variable is used only in while loops with the mutex held, so it does not need a predicate. The entry section locks m; the critical section reads/writes head/tail/n; the exit section unlocks m. The remainder section is empty. Each join waits for its thread to finish.

