Plan: Use a full mutex and condition variable for the buffer; producers inject poison and signal, consumers wait for a valid item or poison.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void *producer(void *p) {
    (void)p; for(int i=0;i<3;i++) { int x=10*i; ck(sem_wait(&space)); ck(pthread_mutex_lock(&m)); buf[full]=x; full=(full+1)%N; ck(pthread_mutex_unlock(&m)); ck(sem_post(&data)); } ck(sem_wait(&space)); ck(pthread_mutex_lock(&m)); buf[full]=-1; full=(full+1)%N; ck(pthread_mutex_unlock(&m)); ck(sem_post(&data)); return NULL;
}
static void *consumer(void *p) {
    (void)p; int x; for(;;) { ck(sem_wait(&data)); ck(pthread_mutex_lock(&m)); if(buf[full]==-1) { ck(pthread_mutex_unlock(&m)); break; } x=buf[full]; full=(full-1)%N; ck(pthread_mutex_unlock(&m)); printf("consumer got %d\n",x); } return NULL;
}
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t data=PTHREAD_COND_INITIALIZER;
static sem_t space, data_sem;
static int buf[N], full=0, N=5;
static void cleanup(void *p) { (void)p; ck(sem_destroy(&space)); ck(sem_destroy(&data_sem)); ck(pthread_mutex_destroy(&m)); }
int main(void) {
    pthread_cleanup_push(cleanup,NULL);
    ck(sem_init(&space,N,5)); ck(sem_init(&data_sem,N,0));
    pthread_t prods[3], cons[2]; for(int i=0;i<3;i++) ck(pthread_create(&prods[i],NULL,producer,NULL));
    for(int i=0;i<2;i++) ck(pthread_create(&cons[i],NULL,consumer,NULL));
    for(int i=0;i<3;i++) ck(pthread_join(prods[i],NULL));
    for(int i=0;i<2;i++) ck(pthread_join(cons[i],NULL));
    ck(sem_destroy(&space)); ck(sem_destroy(&data_sem)); ck(pthread_mutex_destroy(&m)); return 0;
}
```

Why it is correct: The full mutex protects the buffer and full index; space and data_sem are semaphores, not condition variables. A poison item terminates the consumer without polling or a counter. The producer joins before the consumer, so the poison is injected before the consumer waits. The finite producer count and finite buffer size ensure eventual termination.

