Plan: Use a turn flag and a condition variable to coordinate the alternating turns.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <assert.h>
#include <errno.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int turn=0,done=0;
static void *worker(void *p) {
    (void)p;
    for(int i=0;i<10;i++) {
        ck(pthread_mutex_lock(&m));
        while(turn!=(i%2)) ck(pthread_cond_wait(&cv,&m));
        printf("%s\n",turn==0?"ping":"pong");
        turn=1-turn;
        ck(pthread_cond_broadcast(&cv));
        ck(pthread_mutex_unlock(&m));
    }
    done=1;
    return NULL;
}
int main(void) {
    pthread_t t[2];
    ck(pthread_create(&t[0],NULL,worker,NULL));
    ck(pthread_create(&t[1],NULL,worker,NULL));
    for(int i=0;i<2;i++) ck(pthread_join(t[i],NULL));
    ck(pthread_cond_destroy(&cv)); ck(pthread_mutex_destroy(&m));
    assert(done);
    puts("ping-pong completed");
    return 0;
}
```

Why it is correct: The turn flag and condition variable protect the alternating sequence. Each turn is acquired before printing, and broadcast is used after every completion. The finite loop ends when both workers finish.

