        if (customers>=3) { fprintf(stderr,"customer %d leaves\n",id); break; }
        ++customers; sem_wait(&barber_waiting); if (customers==0) { fprintf(stderr,"customer %d woke no barber\n",id); exit(1); }
        --customers; sem_post(&customers); fprintf(stderr,"customer %d served\n",id);
    }
}
