```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int turn=0,N;
static void *worker(void *p) {
    (void)p;
    for(int i=1;i<=N;i++) {
        pthread_mutex_lock(&m);
        while(turn!=(i-1)%3) pthread_cond_wait(&cv,&m);
        printf("%d ",i);
        turn=(i)%3;
        pthread_cond_broadcast(&cv);
        pthread_mutex_unlock(&m);
    }
    return NULL;
}
int main(void) {
    pthread_t t[3];
    ck(pthread_mutex_init(&m,NULL));
    ck(pthread_cond_init(&cv,NULL));
    printf("Enter N: "); scanf("%d",&N);
    for(int i=0;i<3;i++) ck(pthread_create(&t[i],NULL,worker,NULL));
    for(int i=0;i<3;i++) ck(pthread_join(t[i],NULL));
    ck(pthread_cond_destroy(&cv)); ck(pthread_mutex_destroy(&m));
    puts("done");
    return 0;
}
```

Why it is correct: The turn mutex protects the turn variable and the condition variable. Each worker waits for its turn and broadcasts after printing. The broadcast is safe because the turn mutex is held when broadcasting. The while loop ensures the turn is owned before waiting. The broadcast notifies all waiting threads, so the next turn is available.

