Plan: Use a mutex and condition variable to protect the counter and block watchers until zero.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int counter=0;
static void *counter_inc(void *p) {
    (void)p; for(int i=0;i<5;i++) { pthread_mutex_lock(&m); counter++; pthread_cond_broadcast(&cv); pthread_mutex_unlock(&m); } return NULL; }
static void *counter_dec(void *p) {
    (void)p; for(int i=0;i<5;i++) { pthread_mutex_lock(&m); if(counter==0) { pthread_cond_wait(&cv,&m); } --counter; pthread_mutex_unlock(&m); } return NULL; }
static void *wait_until_zero(void *p) {
    (void)p; for(int i=0;i<5;i++) { pthread_mutex_lock(&m); while(counter!=0) pthread_cond_wait(&cv,&m); printf("watcher %d sees zero\n",i); pthread_mutex_unlock(&m); } return NULL; }
static void *unblock(void *p) {
    (void)p; for(int i=0;i<5;i++) { pthread_mutex_lock(&m); counter=0; pthread_cond_broadcast(&cv); pthread_mutex_unlock(&m); } return NULL; }
int main(void) {
    pthread_t t[4]; for(int i=0;i<4;i++) ck(pthread_create(&t[i],NULL,i==0?counter_inc:counter_dec,NULL));
    for(int i=0;i<2;i++) ck(pthread_create(&t[i+4],NULL,wait_until_zero,NULL));
    for(int i=0;i<2;i++) ck(pthread_create(&t[i+6],NULL,unblock,NULL));
    for(int i=0;i<4;i++) ck(pthread_join(t[i],NULL));
    ck(pthread_cond_destroy(&cv)); ck(pthread_mutex_destroy(&m)); printf("done\n"); return 0; }
```

Why it is correct: The mutex protects the counter and condition variable. Each wait_until_zero holds m while checking counter, so it can be unblocked by any counter_dec. Broadcast notifies all waiting watchers, and cv is destroyed after joins. No thread waits for a destroyed cv.

