Plan: Use a mutex for buffer access and two condition variables for full/empty notifications.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void *producer(void *p) {
    (void)p;
    for (int i=0; i<10; ++i) {
        while (count==N) { /* wait for space */ }
        ck(sem_wait(&space)); /* consume space */
        buffer[head]=i; head=(head+1)%N;
        ck(sem_post(&full)); /* notify consumer */
    }
    return NULL;
}
static void *consumer(void *p) {
    (void)p;
    for (int i=0; i<10; ++i) {
        while (count==0) { /* wait for item */ }
        ck(sem_wait(&full)); /* consume item */
        int x=buffer[tail]; tail=(tail+1)%N;
        ck(sem_post(&space)); /* notify producer */
        printf("got %d\n",x);
    }
    return NULL;
}
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t empty=PTHREAD_COND_INITIALIZER,full=PTHREAD_COND_INITIALIZER;
static int buffer[10],head=0,tail=0,count=0,N=10;
static sem_t space,full_sem;
static void ck_sem(int e) { if (e) { fprintf(stderr,"sem error %d\n",e); exit(1); } }
static void *producer_sem(void *p) {
    (void)p;
    for (int i=0; i<10; ++i) {
        ck(sem_wait(&space)); /* consume space */
        buffer[head]=i; head=(head+1)%N;
        ck(sem_post(&full)); /* notify consumer */
    }
    return NULL;
}
static void *consumer_sem(void *p) {
    (void)p;
    for (int i=0; i<10; ++i) {
        ck(sem_wait(&full)); /* consume item */
        int x=buffer[tail]; tail=(tail+1)%N;
        ck(sem_post(&space)); /* notify producer */
        printf("got %d\n",x);
    }
    return NULL;
}
int main(void) {
    ck(pthread_mutex_init(&m,NULL));
    ck(sem_init(&space,0,N)); ck(sem_init(&full_sem,0,0));
    pthread_t t[2]; ck(pthread_create(&t[0],NULL,producer,NULL));
    ck(pthread_create(&t[1],NULL,consumer,NULL));
    for (int i=0; i<2; ++i) ck(pthread_join(t[i],NULL));
    ck(sem_destroy(&space)); ck(sem_destroy(&full_sem));
    ck(pthread_mutex_destroy(&m));
    printf("done\n");
    return 0;
}
```

Why it is correct: The mutex protects head/tail and count; space and full_sem are semaphores, not condition variables. The producer waits for space before writing, and the consumer waits for full before reading. Each item is consumed exactly once, and the finite buffer ensures finite work. The finite wait/signal count avoids indefinite blocking.

