Plan: Use a mutex for each fork and a semaphore for the turn order.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <stdbool.h>
static void ck(int e) { if (e) { fprintf(stderr,"pthread error %d\n",e); exit(1); } }
static void ckp(sem_t *s) { if (sem_trywait(s)==-1 && errno!=EAGAIN) { fprintf(stderr,"sem error\n"); exit(1); } }
static void r(sem_t *s) { ck(sem_wait(s)); }
static void v(sem_t *s) { ck(sem_post(s)); }
static pthread_mutex_t m[5]={PTHREAD_MUTEX_INITIALIZER,...};
static sem_t turn=SEM_INITIALIZER(1);
static void *philosopher(void *p) {
    int id=*(int *)p;
    for(int i=0;i<5;i++) {
        ckp(&m[(id+i)%5]);
        ckp(&m[(id+i+1)%5]);
        r(&turn);
        printf("philosopher %d eats\n",id);
        v(&turn);
        ck(pthread_mutex_unlock(&m[(id+i)%5]));
        ck(pthread_mutex_unlock(&m[(id+i+1)%5]));
    }
    return NULL;
}
int main(void) {
    pthread_t t[5];
    for(int i=0;i<5;i++) ck(pthread_create(&t[i],NULL,philosopher,&i));
    for(int i=0;i<5;i++) ck(pthread_join(t[i],NULL));
    for(int i=0;i<5;i++) ck(pthread_mutex_destroy(&m[i]));
    ck(sem_destroy(&turn)); return 0;
}
```

Why it is correct: Each fork is protected by its own mutex; the turn semaphore enforces a finite execution order, so every philosopher eventually eats. The finite turn order also prevents indefinite waiting and lost wakeups.

